import type { IGeneratedFile } from "./contributions";
import { FileSourceKind, type GeneratedFileSource } from "./lockfile";

/** A generated plugins.txt; content is base64 of the file's bytes. */
export function makeGeneratedFile(
  overrides: Partial<GeneratedFileSource> = {},
): GeneratedFileSource {
  return {
    source: FileSourceKind.VortexGenerated,
    destinationPath: "/fixture-root/appdata/Skyrim Special Edition/plugins.txt",
    fileHash: "plugins-txt-hash",
    content: Buffer.from(
      "# Automatically generated by Vortex\r\n*SkyUI_SE.esp\r\n",
      "latin1",
    ).toString("base64"),
    ...overrides,
  };
}

/** The file a contribution declares for a generated lockfile entry. */
export function makeDeclaredFile(
  generated: GeneratedFileSource = makeGeneratedFile(),
): IGeneratedFile {
  return {
    destinationPath: generated.destinationPath,
    content: Buffer.from(generated.content, "base64"),
  };
}
